// FinishQuizSession is the resolver for the finishQuizSession field.
func (r *mutationResolver) FinishQuizSession(ctx context.Context, id string) (*model.QuizSession, error) {
	ctx, span := otel.StartSpan(ctx, "quiz_session.finish",
		attribute.String("session.id", id),
	)
	defer span.End()

	userID, ok := middleware.GetUserID(ctx)
	if !ok || userID == "" {
		return nil, fmt.Errorf("user not authenticated")
	}

	// Get session with lock
	session, err := r.DB.Queries.GetQuizSessionForUpdate(ctx, id)
	if err != nil {
		otel.RecordError(span, err)
		return nil, fmt.Errorf("failed to load session: %w", err)
	}

	// Load quiz to check authorization
	thunk := r.Loaders.QuizByIDLoader.Load(ctx, session.QuizID)
	quiz, err := thunk()
	if err != nil {
		otel.RecordError(span, err)
		return nil, fmt.Errorf("failed to load quiz: %w", err)
	}
	if quiz == nil {
		return nil, fmt.Errorf("quiz not found")
	}

	// Check if user can manage this session
	if session.CreatedBy != userID && !r.RoleService.CanManageProject(ctx, userID, quiz.ProjectID) {
		return nil, fmt.Errorf("unauthorized to finish this session")
	}

	// Already finalized - return current state (no-op for idempotency)
	if session.State == "FINISHED" {
		return convertQuizSessionToModel(session), nil
	}

	// Only allow finishing from LOCKED state
	if session.State != "LOCKED" {
		return nil, fmt.Errorf("can only finish session from LOCKED state")
	}

	// Update state to FINISHED first to prevent duplicate processing on retry
	row, err := r.DB.Queries.UpdateQuizSessionState(ctx, sqlc.UpdateQuizSessionStateParams{
		ID:    id,
		State: "FINISHED",
	})
	if err != nil {
		otel.RecordError(span, err)
		return nil, fmt.Errorf("failed to finish quiz session: %w", err)
	}

	// Auto-submit all active submissions
	err = r.DB.Queries.AutoSubmitSessionSubmissions(ctx, id)
	if err != nil {
		otel.RecordError(span, err)
		// Log but don't fail - state is already FINISHED
		slog.Error("failed to auto-submit submissions",
			"session_id", id,
			"error", err,
		)
	}

	// Invalidate cache for affected users
	submissions, subErr := r.DB.Queries.GetSessionSubmissionsWithUserData(ctx, id)
	if subErr != nil {
		slog.Warn("failed to get session submissions for cache invalidation",
			"session_id", id,
			"error", subErr,
		)
	} else {
		for _, sub := range submissions {
			r.Cache.InvalidateUser(sub.UserID)
			r.Cache.InvalidateUserQuizSubmissions(sub.UserID)
			r.Cache.InvalidateQuizSubmission(sub.SubmissionID)
		}
	}
	r.Cache.InvalidateProject(quiz.ProjectID)
	r.Cache.InvalidateQuizSession(id)
	r.Cache.InvalidateQuizSessionAccess()

	// Notify clients via Firestore
	if r.FirebaseService != nil {
		go r.FirebaseService.NotifyProjectQuizSessions(context.Background(), quiz.ProjectID)
	}

	// Dispatch quiz_session_finished webhook
	if r.WebhookService != nil {
		go func() {
			// Build webhook payload in background
			submissions, err := r.DB.Queries.GetSessionSubmissionsWithUserData(context.Background(), id)
			if err != nil {
				return
			}

			results := make([]webhooks.QuizUserResult, 0, len(submissions))
			for _, sub := range submissions {
				var scorePercent *float64
				if sub.Score != nil && sub.MaxScore != nil && *sub.MaxScore > 0 {
					percent := float64(*sub.Score) / float64(*sub.MaxScore) * 100
					scorePercent = &percent
				}

				results = append(results, webhooks.QuizUserResult{
					UserID:        sub.UserID,
					MembersID:     sub.MembersID,
					ChurchID:      sub.ChurchID,
					Score:         sub.Score,
					MaxScore:      sub.MaxScore,
					ScorePercent:  scorePercent,
					Completed:     sub.Completed,
					AutoSubmitted: sub.AutoSubmitted,
				})
			}

			sessionName := ""
			if session.Name != nil {
				sessionName = *session.Name
			}

			r.WebhookService.DispatchQuizSessionFinished(context.Background(), quiz.ProjectID, webhooks.QuizSessionFinishedData{
				SessionID:   id,
				SessionName: sessionName,
				QuizID:      quiz.ID,
				QuizName:    quiz.Name,
				ChallengeID: quiz.ChallengeID,
				FinishedAt:  time.Now().UTC(),
				Results:     results,
			})
		}()
	}

	return convertQuizSessionToModel(row), nil
}

