// StartQuizSession is the resolver for the startQuizSession field.
func (r *mutationResolver) StartQuizSession(ctx context.Context, sessionID string) (*model.QuizSubmission, error) {
	ctx, span := otel.StartSpan(ctx, "quiz_session.start",
		attribute.String("session.id", sessionID),
	)
	defer span.End()

	userID, ok := middleware.GetUserID(ctx)
	if !ok || userID == "" {
		return nil, fmt.Errorf("user not authenticated")
	}
	otel.SetUserID(span, userID)

	// Get session (Ristretto-cached with a short TTL; state-changing
	// mutations and the scheduler call InvalidateQuizSession)
	session, err := r.Loaders.QuizSessionByIDLoader.Load(ctx, sessionID)()
	if err != nil || session == nil {
		otel.RecordError(span, err)
		return nil, fmt.Errorf("failed to load session: %w", err)
	}

	// Check session state
	if session.State != "OPEN" {
		return nil, fmt.Errorf("session is not open")
	}

	// Check user has access
	hasAccess, err := r.DB.Queries.HasQuizSessionAccess(ctx, sqlc.HasQuizSessionAccessParams{
		Sessionid: sessionID,
		Userid:    userID,
	})
	if err != nil {
		otel.RecordError(span, err)
		return nil, fmt.Errorf("failed to check access: %w", err)
	}
	if !hasAccess {
		return nil, fmt.Errorf("you do not have access to this session")
	}

	// Check if user already has a submission for this session
	existingSub, err := r.DB.Queries.GetSubmissionByUserAndSession(ctx, sqlc.GetSubmissionByUserAndSessionParams{
		Sessionid: sessionID,
		Userid:    userID,
	})
	if err == nil && existingSub != nil {
		// Return existing submission
		return convertGetSubmissionByUserAndSessionRow(existingSub), nil
	}

	// Load quiz to get questions
	thunk := r.Loaders.QuizByIDLoader.Load(ctx, session.QuizID)
	quiz, err := thunk()
	if err != nil {
		otel.RecordError(span, err)
		return nil, fmt.Errorf("failed to load quiz: %w", err)
	}
	if quiz == nil {
		return nil, fmt.Errorf("quiz not found")
	}

	// Get quiz questions (Ristretto-cached static data)
	questions, err := r.Loaders.QuizQuestionsByQuizLoader.Load(ctx, session.QuizID)()
	if err != nil {
		otel.RecordError(span, err)
		return nil, fmt.Errorf("failed to load quiz questions: %w", err)
	}

	if len(questions) == 0 {
		return nil, fmt.Errorf("quiz has no questions")
	}

	// Build question order (optionally randomized)
	questionIDs := make([]string, len(questions))
	for i, q := range questions {
		questionIDs[i] = q.GetID()
	}

	if quiz.RandomizeQuestions {
		rand.Shuffle(len(questionIDs), func(i, j int) {
			questionIDs[i], questionIDs[j] = questionIDs[j], questionIDs[i]
		})
	}

	questionOrderJSON, err := json.Marshal(questionIDs)
	if err != nil {
		otel.RecordError(span, err)
		return nil, fmt.Errorf("failed to marshal question order: %w", err)
	}

	// Calculate max score
	var maxScore int32
	for _, q := range questions {
		if q.GetPoints() != nil {
			maxScore += int32(*q.GetPoints())
		}
	}

	// Calculate expiry if quiz has timeout
	var expiresAt pgtype.Timestamptz
	if quiz.TimeoutSeconds != nil {
		expiry := time.Now().Add(time.Duration(*quiz.TimeoutSeconds) * time.Second)
		expiresAt = pgtype.Timestamptz{Time: expiry, Valid: true}
	}

	// Create submission with session_id
	params := sqlc.CreateQuizSubmissionParams{
		ID:            ulid.NewQuizSubmissionID(),
		Quizid:        session.QuizID,
		Userid:        userID,
		Sessionid:     &sessionID,
		Expiresat:     expiresAt,
		Questionorder: questionOrderJSON,
		Maxscore:      maxScore,
	}

	row, err := r.DB.Queries.CreateQuizSubmission(ctx, params)
	if err != nil {
		otel.RecordError(span, err)
		return nil, fmt.Errorf("failed to create submission: %w", err)
	}

	return convertCreateQuizSubmissionRow(row), nil
}

// ResetQuizSessionSubmission is the resolver for the resetQuizSessionSubmission field.
func (r *mutationResolver) ResetQuizSessionSubmission(ctx context.Context, sessionID string) (bool, error) {
	ctx, span := otel.StartSpan(ctx, "quiz_session.reset_submission",
		attribute.String("session.id", sessionID),
	)
	defer span.End()

	userID, ok := middleware.GetUserID(ctx)
	if !ok || userID == "" {
		return false, fmt.Errorf("user not authenticated")
	}

	// Get session
	session, err := r.DB.Queries.GetQuizSession(ctx, sessionID)
	if err != nil {
		otel.RecordError(span, err)
		return false, fmt.Errorf("failed to load session: %w", err)
	}

	// Check session state - can only reset while OPEN
	if session.State != "OPEN" {
		return false, fmt.Errorf("can only reset submission while session is open")
	}

	// Delete the user's submission for this session
	err = r.DB.Queries.DeleteSubmissionByUserAndSession(ctx, sqlc.DeleteSubmissionByUserAndSessionParams{
		Sessionid: sessionID,
		Userid:    userID,
	})
	if err != nil {
		otel.RecordError(span, err)
		return false, fmt.Errorf("failed to delete submission: %w", err)
	}

	return true, nil
}

